mapper.select:
SELECT c.id, c.name, c.description, c.cover, c.owner_id, c.member_count, c.post_count, c.category, c.status, c.created_time, pu.nickname AS owner_name, pu.avatar AS owner_avatar FROM portal_circle c LEFT JOIN portal_user pu ON pu.id = c.owner_id
AND (c.name LIKE CONCAT('%', #{query.keyword}, '%') OR c.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND c.status = #{query.status}
AND c.category = #{query.category}
ORDER BY c.created_time DESC
